/* Mapa isométrico elevado: a malha inteira é um tabuleiro 3D, não um overlay plano. */
.city{perspective:1050px;perspective-origin:50% 46%;background:radial-gradient(ellipse at 50% 45%,#34494b 0%,#1b252b 75%)}
.city-map{inset:5% 7%;overflow:visible;transform:rotateX(53deg) rotateZ(-7deg) scale(1.12);transform-origin:50% 50%;transform-style:preserve-3d;border:5px solid #9a9875;border-radius:8px;background:linear-gradient(145deg,#34494b,#202f34 70%,#1b292e);box-shadow:0 12px 0 #131b1f,0 22px 0 #0c1115,0 32px 32px #000b,inset 0 0 0 3px #101a1e,inset 0 0 35px #0b111888}
.city-map:after{content:none}
.map-road{transform-style:preserve-3d;border:2px solid #66716d;border-radius:3px;background:linear-gradient(180deg,#454d4b,#303938 48%,#252d2d);box-shadow:0 8px 0 #151c1c,0 13px 10px #080c0c99,inset 0 2px 0 #ffffff20,inset 0 -3px 0 #111716}
.road-one{transform:translateZ(5px) rotate(-12deg)}.road-two{transform:translateZ(6px) rotate(14deg)}.road-three{transform:translateZ(7px) rotate(9deg)}
.map-road:after{border-color:#e1d8a477;filter:drop-shadow(0 1px 0 #111)}
.map-block{overflow:visible;transform:translateZ(20px);border:2px solid #81948a;border-radius:2px;background:linear-gradient(145deg,#4c6860,#2b4441 70%);box-shadow:0 9px 0 #1b2b2b,0 17px 0 #142020,0 23px 12px #080d0dcc,inset 0 2px 0 #ffffff32,inset 0 -4px 0 #152321;transform-style:preserve-3d}
.map-block:before{content:'';position:absolute;left:5px;right:5px;bottom:-13px;height:13px;background:linear-gradient(180deg,#273b38,#152321);clip-path:polygon(0 0,100% 0,94% 100%,6% 100%);filter:brightness(.85);pointer-events:none}
.map-block i{position:relative;z-index:1;transform:translateZ(10px);filter:drop-shadow(0 4px 2px #000b)}
.block-two,.block-five{background:linear-gradient(145deg,#526477,#2a3948 70%);border-color:#899aa2}.block-four,.block-six{background:linear-gradient(145deg,#526c51,#2b4432 70%);border-color:#8eaa78}
.city.zone-neon .city-map{background:linear-gradient(145deg,#583968,#302747 70%,#211b31);border-color:#d94eff;box-shadow:0 12px 0 #281630,0 22px 0 #150d24,0 32px 32px #000b,inset 0 0 0 3px #321a43}
.city.zone-arcane .city-map{background:linear-gradient(145deg,#476449,#2c4935 70%,#1e3227);border-color:#b6cf86;box-shadow:0 12px 0 #26351f,0 22px 0 #121b17,0 32px 32px #000b,inset 0 0 0 3px #2c3b31}
.city.zone-neon .map-block{background:linear-gradient(145deg,#704883,#392b50);box-shadow:0 9px 0 #281630,0 17px 0 #1b1024,0 23px 12px #080d0dcc,inset 0 2px 0 #ffffff32}
.city.zone-arcane .map-block{background:linear-gradient(145deg,#5b7956,#344d38);box-shadow:0 9px 0 #26351f,0 17px 0 #18251a,0 23px 12px #080d0dcc,inset 0 2px 0 #ffffff32}
@media(max-width:680px){.city-map{inset:9% 4%;transform:rotateX(53deg) rotateZ(-7deg) scale(1.08)}.map-block{transform:translateZ(16px)}}
</style>

