   {id:'fusion',name:'Núcleo de Fusão',icon:'⚛️',desc:'Gera energia limpa e aumenta a renda em 18% por nível.',baseCost:250000,growth:1.62,mult:.18,unlock:0,baseUnlock:3},
   {id:'nanoforge',name:'Nanoforja Autônoma',icon:'🧬',desc:'Nanotecnologia que amplia a renda em 25% por nível.',baseCost:2500000,growth:1.7,mult:.25,unlock:0,baseUnlock:4},
   {id:'quantum',name:'Computador Quântico',icon:'💠',desc:'Otimiza operações e aumenta a renda em 35% por nível.',baseCost:25000000,growth:1.78,mult:.35,unlock:0,baseUnlock:5},
