 ]
};
const SAVE_KEY='sentinelas-save-v1';
const OCCURRENCE_INTERVAL=20*60*1000;
const MINOR_BOSSES=[{name:'ROBÔ DESGOVERNADO',face:'🤖',hp:18},{name:'LADRÃO DE ENERGIA',face:'🦹',hp:22},{name:'GÓLEM DE SUCATA',face:'🪨',hp:26}];
const BASE_COSTS=[100000,1000000,10000000,100000000,1000000000];
const ZONE_COSTS=[0,10000000000,100000000000];
const BOSSES=[
 {name:'O DEVASTADOR',face:'👹',hp:90,time:25,zone:1},
 {name:'MECHA-CAOS',face:'🤖',hp:270,time:30,zone:1},
 {name:'DRAGÃO DE NEON',face:'🐲',hp:750,time:35,zone:2},
 {name:'SENHOR DAS SOMBRAS',face:'💀',hp:2100,time:40,zone:2,phases:3},
 {name:'TITÃ DO FIM',face:'👾',hp:6000,time:45,zone:3,phases:3}
];
const ZONES=[{name:'REFÚGIO URBANO',theme:'urban'},{name:'CIDADE NEON',theme:'neon'},{name:'FORTALEZA ARCANA',theme:'arcane'}];
const ZONE_FIELDS=['credits','counts','clickLevels','last','totalEarned','combo','lastClick','mission','bossActive','bossHP','bossMax','bossTimeLeft','baseLevel','bossLevel','bossCostPaid','teamHP','occurrenceAt','occurrenceReady','minorBattle','minorBoss','minorBossHP','minorHeroHP','minorBuffUntil','healElapsed','bossAttackElapsed','bossPhase'];
function newZoneState(zone){const firstBoss=(zone-1)*2;return{credits:0,counts:{},clickLevels:{},last:Date.now(),totalEarned:0,combo:0,lastClick:0,mission:0,bossActive:false,bossHP:0,bossMax:0,bossTimeLeft:0,baseLevel:firstBoss+1,bossLevel:firstBoss,bossCostPaid:0,zone,teamHP:100,occurrenceAt:Date.now()+OCCURRENCE_INTERVAL,occurrenceReady:false,minorBattle:false,minorBoss:0,minorBossHP:0,minorHeroHP:100,minorBuffUntil:0,healElapsed:0,bossAttackElapsed:0,bossPhase:1}}
let state={...newZoneState(1),zoneStates:{},unlockedZones:1};
let currentTab='heroes',toastTimer,sceneSignature='';
const $=id=>document.getElementById(id);
const compact=n=>{if(n>=1e12)return (n/1e12).toFixed(2)+'T';if(n>=1e9)return (n/1e9).toFixed(2)+'B';if(n>=1e6)return (n/1e6).toFixed(2)+'M';if(n>=1e4)return (n/1e3).toFixed(1)+'K';return Math.floor(n).toLocaleString('pt-BR')};
const allItems=()=>[...DATA.heroes,...DATA.vehicles,...DATA.gear,...shopItems()];
const count=id=>state.counts[id]||0;
function nextZoneIndex(){return state.zone*2-1}
function snapshotZone(){const snap={};for(const key of ZONE_FIELDS)snap[key]=state[key];return snap}
function persistZone(){state.zoneStates=state.zoneStates||{};state.zoneStates[String(state.zone)]=snapshotZone()}
function switchZone(zone){if(zone<1||zone>state.unlockedZones||zone===state.zone)return;persistZone();const zones=state.zoneStates,unlocked=state.unlockedZones,stored=zones[String(zone)]||newZoneState(zone);state={...state,...stored,zone,zoneStates:zones,unlockedZones:unlocked};sceneSignature='';missionElapsed=0;autoClickAccumulator=0;render();renderShop();save()}
function renderZonePicker(){const nav=$('zonePicker');if(!nav)return;nav.innerHTML=ZONES.map((item,index)=>{const zone=index+1,open=zone<=state.unlockedZones;return `<button type="button" class="zone-option ${zone===state.zone?'active':''}" data-zone="${zone}" ${open?'':'disabled'}>${open?'ZONA':'🔒'} 0${zone}${!open&&zone===state.unlockedZones+1?` · ${compact(ZONE_COSTS[zone-1])}`:''}</button>`}).join('');nav.querySelectorAll('[data-zone]').forEach(button=>button.addEventListener('click',()=>switchZone(Number(button.dataset.zone))))}
function shopItems(){if(currentTab==='base'){const index=state.bossActive?state.bossLevel:state.baseLevel-1;if(index>=state.zone*2)return[];const boss=BOSSES[index];if(!boss||boss.zone!==state.zone)return[];return[{id:'baseUpgrade',name:state.bossActive?'Defesa da Base':'Upgrade de Base',icon:state.bossActive?'⚠️':'🏙️',desc:state.bossActive?`${boss.name} está atacando! Derrote-o antes que o tempo acabe.`:`Evolua para a Base nível ${state.baseLevel+1} e enfrente ${boss.name}.`,baseCost:state.bossActive?state.bossCostPaid:BASE_COSTS[index],growth:1,base:true}]}return DATA[currentTab]||[]}
function advanceZone(){const next=state.zone+1;if(next>3||state.bossActive||state.minorBattle||state.bossLevel<state.zone*2-1)return;const price=ZONE_COSTS[next-1];if(state.credits<price){notify(`SÃO NECESSÁRIOS ${compact(price)} CRÉDITOS PARA ABRIR A ZONA`);return}state.credits-=price;persistZone();state.unlockedZones=Math.max(state.unlockedZones,next);state.zoneStates[String(next)]=newZoneState(next);const zones=state.zoneStates,unlocked=state.unlockedZones;state={...state,...zones[String(next)],zone:next,zoneStates:zones,unlockedZones:unlocked};sceneSignature='';missionElapsed=0;autoClickAccumulator=0;notify(`NOVA ZONA ABERTA · ${ZONES[next-1].name}`);render();renderShop();save()}
function baseMultiplier(){return Math.pow(1.15,Math.max(0,state.baseLevel-1))}
function debuffMultiplier(){return state.teamHP<50?.5:1}
 function passive(){const base=DATA.heroes.reduce((sum,item)=>sum+count(item.id)*item.gps,0);return base*multiplier()*baseMultiplier()*debuffMultiplier()}
 function healTeam(){state.teamHP=100;state.minorHeroHP=100;notify('EQUIPE RESTAURADA · VIDA 100%');render();save()}
 function healerCount(){return count('healer')}
function regenTeam(dt){const healers=healerCount();if(healers){state.healElapsed=(state.healElapsed||0)+dt;while(state.healElapsed>=30){state.healElapsed-=30;state.teamHP=Math.min(100,state.teamHP+healers)}}else state.healElapsed=0;state.minorHeroHP=state.teamHP}
 function autoHitDps(){return DATA.gear.filter(i=>i.autoHit).reduce((sum,item)=>sum+count(item.id)*item.autoHit*clickPower()*hitsPerAttack(),0)}
 function defenseMultiplier(){return Math.max(.2,1-DATA.gear.filter(i=>i.defense).reduce((sum,item)=>sum+count(item.id)*item.defense,0))}
function moneyMultiplier(){return state.minorBuffUntil>Date.now()?2:1}
function earn(amount){const gained=amount*moneyMultiplier();state.credits+=gained;state.totalEarned+=gained;return gained}
function multiplier(){return 1+DATA.gear.filter(i=>i.mult).reduce((s,i)=>s+count(i.id)*i.mult,0)}
function missionDuration(){return Math.max(3,10-DATA.vehicles.reduce((s,i)=>s+count(i.id)*(i.bonus?i.bonus*14:0),0))}
function missionReward(){return Math.max(5,Math.round((5+passive()*.45)*(1+Math.log10(1+state.totalEarned/1000)*.15)))}
function clickPower(){return 1+DATA.gear.filter(i=>i.click).reduce((s,i)=>s+count(i.id)*i.click,0)}
 function hitsPerAttack(){return Math.min(10,1+count('comboGloves'))}
function repLevel(){return Math.max(1,Math.floor(Math.sqrt(state.totalEarned/250))+1)}
function teamCount(){return DATA.heroes.reduce((s,i)=>s+count(i.id),0)}
function save(){state.last=Date.now();persistZone();try{localStorage.setItem(SAVE_KEY,JSON.stringify(state))}catch(e){}}
function load(){try{const raw=localStorage.getItem(SAVE_KEY);if(raw){const parsed=JSON.parse(raw),now=Date.now();state={...state,...parsed};state.zone=Math.max(1,Math.min(3,Number(state.zone)||1));state.unlockedZones=Math.max(state.zone,Math.min(3,Number(state.unlockedZones)||1));state.zoneStates=parsed.zoneStates&&typeof parsed.zoneStates==='object'?parsed.zoneStates:{};if(!state.zoneStates[String(state.zone)]){const legacy={...newZoneState(state.zone)};for(const key of ZONE_FIELDS)if(parsed[key]!==undefined)legacy[key]=parsed[key];state.zoneStates[String(state.zone)]=legacy}for(let zone=1;zone<=state.unlockedZones;zone++){const saved=state.zoneStates[String(zone)];state.zoneStates[String(zone)]={...newZoneState(zone),...(saved||{})}}Object.assign(state,state.zoneStates[String(state.zone)],{zone:state.zone,zoneStates:state.zoneStates,unlockedZones:state.unlockedZones});state.counts=state.counts||{};state.clickLevels=state.clickLevels||{};state.baseLevel=Math.max(1,Math.min(BASE_COSTS.length+1,Number(state.baseLevel)||1));state.teamHP=Math.max(0,Math.min(100,Number.isFinite(Number(state.teamHP))?Number(state.teamHP):100));state.minorHeroHP=state.teamHP;state.bossLevel=Math.max((state.zone-1)*2,Math.min(Math.min(BOSSES.length-1,state.zone*2-1),Number(state.bossLevel)||0));state.healElapsed=Math.max(0,Number(state.healElapsed)||0)%30;state.bossAttackElapsed=Math.max(0,Number(state.bossAttackElapsed)||0)%5;state.bossPhase=Math.max(1,Number(state.bossPhase)||1);if(state.bossActive&&(!Object.prototype.hasOwnProperty.call(parsed,'bossCostPaid')||!state.bossCostPaid)){state.bossActive=false;state.bossHP=0;state.bossTimeLeft=0;state.bossCostPaid=0}if(!Number.isFinite(state.occurrenceAt))state.occurrenceAt=now+OCCURRENCE_INTERVAL;state.occurrenceReady=!!state.occurrenceReady;state.minorBattle=!!state.minorBattle;state.minorBoss=Math.max(0,Math.min(MINOR_BOSSES.length-1,Number(state.minorBoss)||0));state.minorBossHP=Number(state.minorBossHP)||0;state.minorBuffUntil=Number(state.minorBuffUntil)||0;const last=state.last||now,away=Math.max(0,Math.min(8*3600,(now-last)/1000)),buffSeconds=Math.max(0,Math.min(away,(state.minorBuffUntil-last)/1000)),earned=passive()*(away+buffSeconds);state.credits+=earned;state.totalEarned+=earned;if(state.minorBattle&&state.minorBossHP<=0){state.minorBattle=false;state.minorHeroHP=state.teamHP}if(state.occurrenceAt<=now&&!state.occurrenceReady&&!state.minorBattle){state.occurrenceReady=true;state.occurrenceAt=0}if(earned>=1){$('offlineEarned').textContent='+'+compact(earned)+' créditos';$('offlineOverlay').classList.add('show')}}}catch(e){console.warn('Save indisponível',e)}}
function cost(item){if(item.base)return item.baseCost;const n=item.id in state.counts?count(item.id):0;return Math.ceil(item.baseCost*Math.pow(item.growth,n))}
